import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"企业知识问答系统","description":"项目契约：使用真实 RAG 链路实现企业文档入库、权限检索、引用回答、反馈与评测。","frontmatter":{"title":"企业知识问答系统","description":"项目契约：使用真实 RAG 链路实现企业文档入库、权限检索、引用回答、反馈与评测。","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"py-agent/architecture/projects/enterprise-knowledge-qa-system.md","filePath":"py-agent/architecture/projects/enterprise-knowledge-qa-system.md","lastUpdated":null}'),i={name:"py-agent/architecture/projects/enterprise-knowledge-qa-system.md"};function l(n,e,s,c,p,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="企业知识问答系统" tabindex="-1">企业知识问答系统 <a class="header-anchor" href="#企业知识问答系统" aria-label="Permalink to &quot;企业知识问答系统&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本项目是项目实战主线的第一项，类型为 <strong>RAG 应用</strong>。它先完成稳定的检索与引用闭环，不为了使用 Agent 而引入不必要的自主决策。</p><h2 id="项目结果" tabindex="-1">项目结果 <a class="header-anchor" href="#项目结果" aria-label="Permalink to &quot;项目结果&quot;">​</a></h2><p>读者最终会得到一个可通过 HTTP 调用的知识问答服务：管理员能够导入和更新文档，用户只能检索当前租户和角色有权访问的 Chunk，回答必须携带可回查引用，证据不足时明确拒答，反馈能够进入离线评测数据集。</p><h2 id="实现范围" tabindex="-1">实现范围 <a class="header-anchor" href="#实现范围" aria-label="Permalink to &quot;实现范围&quot;">​</a></h2><ul><li>FastAPI 提供文档、索引任务、问答、来源和反馈接口；</li><li>LangChain 负责 Loader、Splitter、Embedding、Retriever 和回答链；</li><li>PostgreSQL 保存文档元数据、权限、版本、反馈和任务状态；</li><li>pgvector 保存向量并在数据库内完成租户与 ACL 过滤；</li><li>后台任务执行文档解析、切分和索引更新；</li><li>自动化测试覆盖检索、引用、拒答、版本切换和越权访问；</li><li>Docker Compose 提供 API、Worker 和 PostgreSQL/pgvector 环境。</li></ul><h2 id="验收基线" tabindex="-1">验收基线 <a class="header-anchor" href="#验收基线" aria-label="Permalink to &quot;验收基线&quot;">​</a></h2><p>项目必须展示从原始文档到最终引用答案的完整数据流，并实际验证新增、更新、删除、无答案、跨租户访问和旧版本隔离。前端管理界面、OCR 和复杂表格解析不属于第一版范围。</p>',9)])])}const _=t(i,[["render",l]]);export{u as __pageData,_ as default};
